// Buffer control
LowLatencyLayout layout(rdma_buffer_ptr, num_max_dispatch_tokens_per_rank, hidden, num_ranks, num_experts);
EP_HOST_ASSERT(layout.total_bytes <= num_rdma_bytes);
auto buffer = layout.buffers[low_latency_buffer_idx];
auto next_buffer = layout.buffers[low_latency_buffer_idx ^= 1];

// Wait previous tasks to be finished
// NOTES: the hook mode will always use the default stream
auto compute_stream = at::cuda::getCurrentCUDAStream();
auto launch_stream = return_recv_hook ? compute_stream : comm_stream;
EP_HOST_ASSERT(not (async and return_recv_hook));
if (not return_recv_hook)
    stream_wait(launch_stream, compute_stream);

launcher(return_recv_hook ? LOW_LATENCY_SEND_PHASE : (LOW_LATENCY_SEND_PHASE | LOW_LATENCY_RECV_PHASE));

// Wait streams
std::optional<EventHandle> event;
if (async) {
    // NOTES: we must ensure the all tensors will not be deallocated before the stream-wait happens,
    // so in Python API, we must wrap all tensors into the event handle.
    event = EventHandle(launch_stream);
} else if (not return_recv_hook) {
    stream_wait(compute_stream, launch_stream);
}

// Receiver callback
std::optional<std::function<void()>> recv_hook = std::nullopt;
if (return_recv_hook)
    recv_hook = [=]() { launcher(LOW_LATENCY_RECV_PHASE); };

// Return values
return {packed_recv_x, packed_recv_x_scales, packed_recv_count, packed_recv_src_info, packed_recv_layout_range, event, recv_hook};

LowLatencyLayout layout(rdma_buffer_ptr, num_max_dispatch_tokens_per_rank, hidden, num_ranks, num_experts);
EP_HOST_ASSERT(layout.total_bytes <= num_rdma_bytes);
auto buffer = layout.buffers[low_latency_buffer_idx];
auto next_buffer = layout.buffers[low_latency_buffer_idx ^= 1];

// Wait previous tasks to be finished
// NOTES: the hook mode will always use the default stream
auto compute_stream = at::cuda::getCurrentCUDAStream();
auto launch_stream = return_recv_hook ? compute_stream : comm_stream;
EP_HOST_ASSERT(not (async and return_recv_hook));
if (not return_recv_hook)
    stream_wait(launch_stream, compute_stream);

launcher(return_recv_hook ? LOW_LATENCY_SEND_PHASE : (LOW_LATENCY_SEND_PHASE | LOW_LATENCY_RECV_PHASE));

// Wait streams
std::optional<EventHandle> event;
if (async) {
    // NOTES: we must ensure the all tensors will not be deallocated before the stream-wait happens,
    // so in Python API, we must wrap all tensors into the event handle.
    event = EventHandle(launch_stream);
} else if (not return_recv_hook) {
    stream_wait(compute_stream, launch_stream);
}

// Receiver callback
std::optional<std::function<void()>> recv_hook = std::nullopt;
if (return_recv_hook)
    recv_hook = [=]() { launcher(LOW_LATENCY_RECV_PHASE); };

// Return values
return {combined_x, event, recv_hook};

// The first SM is also responsible for cleaning the next buffer
#pragma unroll
for (int i = lane_id; i < num_next_clean_int; i += 32)
    next_clean[i] = 0;

// Notify before executing `int_p`
__syncwarp();
#pragma unroll
for (int i = lane_id; i < num_experts; i += 32)
    atomic_add_release_global(atomic_finish_counter_per_expert + i, FINISHED_SUM_TAG);

// Issue count sends
if (responsible_expert_idx < num_experts and sub_warp_id == 0 and lane_id == 0) {
    const auto dst_rank = responsible_expert_idx / num_local_experts;
    const auto dst_expert_local_idx = responsible_expert_idx % num_local_experts;
    const auto num_tokens_sent = shared_num_tokens_sent_per_expert[responsible_expert_idx - sm_id * num_warp_groups];

    // Wait local sends issued and send expert counts
    while (ld_acquire_global(atomic_finish_counter_per_expert + responsible_expert_idx) != FINISHED_SUM_TAG * 2);
    auto dst_ptr = reinterpret_cast<uint64_t>(rdma_recv_count + dst_expert_local_idx * num_ranks + rank);
    auto dst_p2p_ptr = nvshmemi_get_p2p_ptr(dst_ptr, rank, dst_rank);
    if (dst_p2p_ptr == 0) {
        nvshmemi_ibgda_amo_nonfetch_add(reinterpret_cast<int*>(dst_ptr), -num_tokens_sent - 1, dst_rank, dst_expert_local_idx);
    } else {
        st_release_sys_global(reinterpret_cast<int*>(dst_p2p_ptr), -num_tokens_sent - 1);
    }

int num_recv_tokens, recv_token_begin_idx;
EP_DEVICE_ASSERT(num_warps_per_group > 1 and num_warp_groups < 15);
if (sub_warp_id == 1 and lane_id == 0) {
    auto start_time = clock64();
    while ((num_recv_tokens = ld_acquire_sys_global(rdma_recv_count + local_expert_idx * num_ranks + src_rank)) == 0);
    auto wait_recv_cost = clock64() - start_time;
    num_recv_tokens = -num_recv_tokens - 1;
    recv_token_begin_idx = atomicAdd(packed_recv_count + local_expert_idx, num_recv_tokens);
    shared_num_recv_tokens[warp_group_id] = num_recv_tokens;
    shared_recv_token_begin_idx[warp_group_id] = recv_token_begin_idx;
    recv_range[src_rank] = pack2<int, int64_t>(num_recv_tokens, recv_token_begin_idx);

// Put the finishing flag
EP_DEVICE_ASSERT(num_warps_per_group > 1 and num_warp_groups < 16);
asm volatile("bar.sync %0, %1;" :: "r"(warp_group_id + 1), "r"(num_warps_per_group * 32));
if (sub_warp_id == 1 and lane_id == 0) {
    while (ld_acquire_global(atomic_clean_flag) == 0);
    auto dst_ptr = reinterpret_cast<uint64_t>(rdma_recv_flag + global_expert_idx);
    auto dst_p2p_ptr = nvshmemi_get_p2p_ptr(dst_ptr, rank, dst_rank);
    if (dst_p2p_ptr == 0) {
        nvshmemi_ibgda_amo_nonfetch_add(reinterpret_cast<int*>(dst_ptr), 1, dst_rank, local_expert_idx);
    } else {
        st_release_sys_global(reinterpret_cast<int*>(dst_p2p_ptr), 1);
    }
    atomic_add_release_global(atomic_clean_flag, -1);
}

    EP_DEVICE_ASSERT(num_warps_per_group > 1);
    if (sub_warp_id == 0 and lane_id == 0) {
        auto start_time = clock64();
        while (ld_acquire_sys_global(rdma_recv_flag + responsible_expert_idx) == 0);
        auto wait_recv_cost = clock64() - start_time;
        if (combine_wait_recv_cost_stats != nullptr) {
            const auto& src_rank = responsible_expert_idx / num_local_experts;
            atomicAdd(reinterpret_cast<unsigned long long*>(combine_wait_recv_cost_stats + src_rank), wait_recv_cost);
        }
    }
}
cg::this_grid().sync();

// Reassign warp groups
constexpr int kMaxNumGroups = 2;
const int num_decode_warps = hidden_bf16_int4_pad / (kNumRecvUnrolls * 32);
const int num_groups = min(kMaxNumGroups, (num_threads / 32) / (num_decode_warps + 1));
const int decode_warp_idx = __shfl_sync(0xffffffff, warp_id % (num_decode_warps + 1), 0);
const int group_idx = __shfl_sync(0xffffffff, warp_id / (num_decode_warps + 1), 0);
EP_STATIC_ASSERT(kHidden % (32 * kNumElemsPerInt4) == 0, "Invalid vectorization");
EP_DEVICE_ASSERT(num_topk <= 32);

nvshmemi_ibgda_quiet(int dst_pe, int qp_id) {
    auto qp = ibgda_get_rc(dst_pe, qp_id);
    auto state = ibgda_get_state();
    uint64_t prod_idx = state->use_async_postsend ? ld_na_relaxed(qp->tx_wq.prod_idx) : ld_na_relaxed(&qp->mvars.tx_wq.ready_head);
    ibgda_poll_cq(qp->tx_wq.cq, prod_idx);
}

static std::optional<EventHandle> stream_control_epilogue(const tensor_list_t& tensors,
                                                          const at::cuda::CUDAStream& compute_stream,
                                                          const bool& allocate_on_comm_stream,
                                                          const bool& async_with_compute_stream) {
    // Ensure memory access safety between two streams
    const auto comm_stream = comm::get_comm_stream();
    std::optional<EventHandle> event;
    if (async_with_compute_stream) {
        event = EventHandle(comm_stream);

        // NOTES: this environment only applies to V2 APIs
        if (get_env<int>("EP_AVOID_RECORD_STREAM", 0)) {
            event->tensors_to_record = tensors;
        } else {
            for (auto& t: tensors) if (t.has_value()) {
                t->record_stream(compute_stream);
                t->record_stream(comm_stream);
            }
        }
    } else {
        comm::stream_wait(compute_stream, comm_stream);
    }

    // Switch back compute stream
    if (allocate_on_comm_stream)
        at::cuda::setCurrentCUDAStream(compute_stream);

    // The CUDA event marking the finishing
    return event;

// Defer epilogue: record the created tensors only, and return intermediately
// NOTES: CPU sync will be deferred, too
if (defer_epilogue) {
    EP_HOST_ASSERT(async_with_compute_stream);
    const auto event = stream_control_epilogue(
        tensors_to_record, compute_stream, allocate_on_comm_stream, true);
    std::function<pybind11::object()> epilogue_hook = [epilogue = std::move(epilogue)]() mutable {
        return epilogue(at::cuda::getCurrentCUDAStream(), std::nullopt);
    };
    return pybind11::make_tuple(pybind11::none(), event, epilogue_hook);
}

// Do epilogue intermediately and record all tensors
auto result = epilogue(comm_stream, std::ref(tensors_to_record));
const auto event = stream_control_epilogue(
    tensors_to_record, compute_stream, allocate_on_comm_stream, async_with_compute_stream);
return pybind11::make_tuple(result, event, pybind11::none());

// Flush all QPs by all SMs (only needed for release semantics)
if constexpr (kFlushStores) {
    for (int i = global_warp_idx; i < num_qps; i += kNumSMs * kNumWarps) {
        ncclGin(nccl_dev_comm, i, NCCL_GIN_RESOURCE_SHARING_CTA).flush(ncclCoopWarp());
    }

    // World-team barriers may mix direct NVLink writes with GIN signals, so a system-scope
    // threadfence is required to make the NVLink writes visible before publishing the barrier
    if constexpr (std::is_same_v<team_t, ncclTeamTagWorld>)
        ptx::fence_acq_rel_sys();

    // NOTES: we can not use `kNumSMs` to judge, as maybe only part of the SMs will call this function
    (gridDim.x > 1) ? cooperative_groups::this_grid().sync() : __syncthreads();
}

if (sm_idx == 0) {
    // Use QP 0 to do barrier: signal slot `rank_idx` on every rank, then wait for every rank's slot
    const NCCLGin barrier_gin(nccl_dev_comm, gin.nccl_window, 0, NCCL_GIN_RESOURCE_SHARING_CTA);
    for (int i = thread_idx; i < kNumRanks; i += kNumThreads)
        barrier_gin.signal<team_t>(i, ncclGin_SignalInc{static_cast<ncclGinSignal_t>(rank_idx)});
    for (int i = thread_idx; i < kNumRanks; i += kNumThreads)
        barrier_gin.wait_signal<team_t, kNumTimeoutCycles>(i, rank_idx);

// Barrier to ensure data arrival
comm::gpu_barrier<kIsScaleupNVLink, 1, kNumRanks,
                  kNumSMs, kNumThreads, kNumQPs, kNumTimeoutCycles, comm::kDispatchTag1, true, true, false>(
    gin, workspace_layout.get_barrier_signals(), 0, rank_idx, sm_idx, thread_idx);

// Full barrier to ensure the remote buffer is available
const auto workspace_layout = layout::EPWorkspaceLayout(workspace, 1, kNumRanks, kNumExperts);
comm::gpu_barrier<kIsScaleupNVLink, 1, kNumRanks,
                  kNumSMs, kNumThreads, kNumQPs, kNumTimeoutCycles, comm::kCombineTag0, false, false, true>(
    gin, workspace_layout.get_barrier_signals(), 0, rank_idx, sm_idx, thread_idx);

    // Final barrier to ensure data arrival
    comm::gpu_barrier<kIsScaleupNVLink, 1, kNumRanks,
                      kNumSMs, kNumThreads, kNumQPs, kNumTimeoutCycles, comm::kCombineTag1, true, true, false>(
        gin, workspace_layout.get_barrier_signals(), 0, rank_idx, sm_idx, thread_idx);
}

// Scale-up barrier to ensure data arrival
// As scale-out tokens have already been consumed by forwarders, no need to do scale-out barrier again
comm::gpu_barrier<true, kNumScaleoutRanks, kNumScaleupRanks,
                  kNumSMs, kNumThreads, kNumQPs, kNumTimeoutCycles, comm::kHybridDispatchTag1, true, true, false>(
    gin, workspace_layout.get_barrier_signals(), scaleout_rank_idx, scaleup_rank_idx, sm_idx, thread_idx, /* do not scale-out */ false, true);

// Trigger the copy epilogue kernel
cudaTriggerProgrammaticLaunchCompletion();

// Update, wait and clean
EP_STATIC_ASSERT(kNumScaleoutRanks <= 32, "Invalid ranks");
const auto expected_signal = math::pack2<int, int64_t>(1, 0);
gin.flush<ncclCoopWarp>();
if (lane_idx < kNumScaleoutRanks) {
    // Update remote tails
    gin.red_add_rel<ncclTeamTagRail>(
        workspace_layout.get_scaleout_channel_signaled_tail_ptr(channel_idx, scaleout_rank_idx),
        expected_signal, lane_idx);
}
__syncwarp();

// Wait tail arrival
if (lane_idx < kNumScaleoutRanks) {
    const auto wait_ptr = workspace_layout.get_scaleout_channel_signaled_tail_ptr(channel_idx, lane_idx);
    comm::timeout_while<kNumTimeoutCycles>([=](const bool& is_last_check) {
        const auto signal = ptx::ld_acquire_sys<int64_t>(wait_ptr);
        if (signal == expected_signal) {

                    // Clean for next usages
                    *wait_ptr = 0;
                    return true;
                }

                if (is_last_check) {
                    printf("DeepEP combine (scale-out wait all) timeout, scale-out: %d/%d, scale-up: %d/%d, "
                           "channel: %d, lane: %d, signal: %lld, expected: %lld\n",
                           scaleout_rank_idx, kNumScaleoutRanks, scaleup_rank_idx, kNumScaleupRanks,
                           channel_idx, lane_idx,
                           signal, expected_signal);
                }
                return false;
            });
        }
        __syncwarp();
    }

    // No barrier at epilogue
}
